const wewnetrzneId = Symbol("id");
const produkt = {
  name: "Rower",
  [wewnetrzneId]: 555
};

console.log(produkt[wewnetrzneId]); // 555

const wewnetrzneId = Symbol("id");
const produkt = { name: "Rower", [wewnetrzneId]: 555 };

console.log(Object.keys(produkt)); // ['name']
// klucz-symbol NIE jest widoczny w wyniku Object.keys() -
// widac wylacznie zwykly, tekstowy klucz 'name'

const kluczA = Symbol("id");
const kluczB = Symbol("id");
const dane = { [kluczA]: "wartosc" };

console.log(dane[kluczB]); // undefined
// kluczB to CALKOWICIE inny symbol niz kluczA, mimo tego samego opisu "id" -
// obiekt 'dane' nie ma zadnej wlasciwosci pod kluczem kluczB

function stworzUnikalnyId(nazwa) {
  return Symbol(nazwa);
}

const id1 = stworzUnikalnyId("uzytkownik");
const id2 = stworzUnikalnyId("uzytkownik");

console.log(id1 === id2); // false

const WERSJA = Symbol("wersja");
const konfiguracja = {
  jezyk: "pl",
  motyw: "ciemny",
  [WERSJA]: "1.0"
};

console.log(JSON.stringify(konfiguracja));
// '{"jezyk":"pl","motyw":"ciemny"}'
// klucz-symbol WERSJA CALKOWICIE znika z wyniku JSON.stringify(),
// mimo ze wlasciwosc realnie istnieje w obiekcie

const bezOpisu = Symbol();
console.log(bezOpisu.description); // undefined
console.log(typeof bezOpisu);      // "symbol"
// Symbol nie wymaga opisu - Symbol() bez argumentow tworzy w pelni
// poprawna, unikalna wartosc typu symbol, tylko bez czytelnej etykiety

const a = Symbol.for("globalny");
const b = Symbol.for("globalny");
console.log(a === b); // true
// Symbol.for() (w odroznieniu od zwyklego Symbol()) korzysta z globalnego
// rejestru symboli - ten sam klucz tekstowy ZAWSZE zwraca DOKLADNIE
// TEN SAM symbol, wiec dwa wywolania z identycznym kluczem sa rowne

console.log(Symbol("x") === Symbol.for("x")); // false
// Symbol('x') tworzy NOWA, unikalna wartosc za kazdym razem -
// Symbol.for('x') szuka/tworzy symbol w GLOBALNYM rejestrze -
// to dwa rozne mechanizmy, wiec ich wyniki nigdy nie sa sobie rowne,
// mimo identycznego tekstu

const TAJNE = Symbol("tajne");
const osoba = { imie: "Kasia" };
osoba[TAJNE] = "PESEL:12345";

console.log(osoba[TAJNE]);       // "PESEL:12345"
console.log(Object.keys(osoba)); // ['imie'] - symbol wciaz niewidoczny

function utworzLicznik() {
  const WARTOSC = Symbol("wartosc");
  return {
    [WARTOSC]: 0,
    zwieksz() {
      this[WARTOSC] = this[WARTOSC] + 1;
      return this[WARTOSC];
    }
  };
}

const licznik = utworzLicznik();
console.log(licznik.zwieksz()); // 1
console.log(licznik.zwieksz()); // 2

const dane = { a: 1, [Symbol("b")]: 2 };
const symbole = Object.getOwnPropertySymbols(dane);
console.log(symbole.length); // 1

const tekst = "test";
const symbol = Symbol("test");
console.log(tekst === symbol.description); // true
// .description zwraca ZWYKLY string (sam opis, bez 'opakowania' Symbol) -
// porownanie dwoch stringow dziala normalnie, wiec moze byc true,
// mimo ze SAM symbol (bez .description) nigdy nie bedzie === ze stringiem

function test() {
  try {
    const wynik = Symbol("a") + "tekst";
  } catch (e) {
    console.log(e.name); // "TypeError"
  }
}

test();

const wynik = String(Symbol("a"));
console.log(wynik, typeof wynik); // "Symbol(a)" "string"
// String() dziala poprawnie (w odroznieniu od + z poprzedniego zadania),
// bo to JAWNA konwersja - wynik to string "Symbol(a)", zawierajacy opis
// w nawiasach, nie sam Symbol

const symbole = [Symbol("a"), Symbol("b"), Symbol("c")];
for (let i = 0; i < symbole.length; i++) {
  console.log(symbole[i].description);
}
// a
// b
// c

const HISTORIA = Symbol("historia");
const konto = { numer: "123", saldo: 500, [HISTORIA]: [] };

konto[HISTORIA].push("wplata");
konto[HISTORIA].push("wyplata");

console.log(konto[HISTORIA]); // ['wplata', 'wyplata']

const KOLOR = Symbol("kolor");
console.log(Boolean(KOLOR)); // true
// Symbol nie jest jedna z szesciu wartosci falsy (lekcja 5) -
// KAZDY symbol, niezaleznie od opisu, jest zawsze truthy

function porownajSymbole(a, b) {
  return a === b;
}

const wspolny = Symbol("wspolny");
console.log(porownajSymbole(wspolny, wspolny)); // true - TA SAMA zmienna

const STAN = Symbol("stan");
const magazyn = { [STAN]: "aktywny" };

function zmienStan(obiekt, nowyStan) {
  obiekt[STAN] = nowyStan;
}

zmienStan(magazyn, "nieaktywny");
console.log(magazyn[STAN]); // "nieaktywny"

console.log(typeof Symbol("a"), typeof "a"); // "symbol" "string"
// mimo ze opis symbolu ("a") wyglada identycznie jak string "a",
// to DWA calkowicie rozne typy - typeof jednoznacznie to potwierdza

const META = Symbol("meta");
const punkty = {
  gracz: "Ala",
  wynik: 100,
  [META]: { utworzono: "2024-01-01" }
};

console.log(punkty[META].utworzono); // "2024-01-01"

function funkcjaA() {
  return Symbol.for("app-config");
}

function funkcjaB() {
  return Symbol.for("app-config");
}

console.log(funkcjaA() === funkcjaB()); // true

function maSymbol(obiekt, symbol) {
  return symbol in obiekt;
}

const A = Symbol("a");
const B = Symbol("b");
const obj = { [A]: 1 };

console.log(maSymbol(obj, A)); // true
console.log(maSymbol(obj, B)); // false

function usunSymbol(obiekt, symbol) {
  delete obiekt[symbol];
}

const X = Symbol("x");
const obj = { [X]: "wartosc" };

console.log(obj[X]); // "wartosc"
usunSymbol(obj, X);
console.log(obj[X]); // undefined

function policzWlasciwosciSymboliczne(obiekt) {
  return Object.getOwnPropertySymbols(obiekt).length;
}

const obj = {
  zwykla: 1,
  [Symbol("a")]: 2,
  [Symbol("b")]: 3,
  [Symbol("c")]: 4
};

console.log(policzWlasciwosciSymboliczne(obj)); // 3

const A = Symbol("a");
const B = Symbol("b");
const uzytkownik = { imie: "Tom", [A]: 1, [B]: 2 };

console.log(Reflect.ownKeys(uzytkownik));
// ['imie', Symbol(a), Symbol(b)] - Reflect.ownKeys widzi WSZYSTKO

console.log(typeof Symbol() === "symbol");   // true
console.log(Symbol() instanceof Symbol);     // false
// Symbol to prymityw, nie obiekt - instanceof (sprawdzajace lancuch
// prototypow obiektow) zawsze zwraca false dla wartosci prymitywnych

function utworzEnum(nazwy) {
  const enumObj = {};
  for (let i = 0; i < nazwy.length; i++) {
    enumObj[nazwy[i]] = Symbol(nazwy[i]);
  }
  return enumObj;
}

const Kolor = utworzEnum(["CZERWONY", "ZIELONY", "NIEBIESKI"]);
console.log(Kolor.CZERWONY !== Kolor.ZIELONY); // true - kazda wartosc unikalna

